       tag=\$(echo \"\$json\" | grep -oE '\"tag_name\": *\"[a-zA-Z0-9_.-]+\"' | sed 's/.*\"tag_name\": *\"//;s/\"//' | head -1)
    fi
    if [[ -n \"\${tag:-}\" && \"\$tag\" != \"null\" ]]; then 
