function get_mysql_image_name() {
    local image arch=\"\$(get_docker_arch)\"
    if [[ \"\$arch\" == arm ]]; then
        # https://github.com/beercan1989/docker-arm-mysql
        image=\"beercan1989/arm-mysql:latest\"
    elif [[ \"\$arch\" == arm64 && \"\$MYSQL_VERSION\" == \"5.7\" ]]; then
