        sed_cmd='/<LangVersion>/c\x5C<LangVersion>'\$LANGUAGE'<\x5C/LangVersion>'
        # printf \"    sed cmd: [\$sed_cmd]\x5Cn\"
        sed -i \"\$sed_cmd\" \$csproj
      else
        echo \"    Warning! <LangVersion> not found, but language was specified as \$LANGUAGE\"
      fi
    fi

  
   

  # echo \$lines
