# say Green|Yellow|Red Hello World without quotes
Colorize() { 
   local str1st=\"\${1:-}\"
   str1st=\"\$(To_Lower_Case \"\$str1st\")\"
   local newLine=\"\x5Cn\"
   if [[ \"\$str1st\" == \"--nonewline\" ]] || [[ \"\$str1st\" == \"-nonewline\" ]]; then newLine=\"\"; shift; fi
   
   local NC='\x5C033[0m' Color_White='\x5C033[1;37m' Color_Black='\x5C033[1;30m' \x5C
         Color_Red='\x5C033[1;31m' Color_Green='\x5C033[1;32m' Color_Yellow='\x5C033[1;33m' Color_Blue='\x5C033[1;34m' Color_Magenta='\x5C033[1;35m' Color_Cyan='\x5C033[1;36m' \x5C
         Color_LightRed='\x5C033[0;31m' Color_LightGreen='\x5C033[0;32m' Color_LightYellow='\x5C033[0;33m' Color_LightBlue='\x5C033[0;34m' Color_LightMagenta='\x5C033[0;35m' Color_LightCyan='\x5C033[0;36m' Color_LightWhite='\x5C033[0;37m' \x5C
         Color_Purple='\x5C033[0;35m' Color_LightPurple='\x5C033[1;35m'
   # local var=\"Color_\${1:-}\"
   # local color=\"\"; [[ -n \${!var+x} ]] && color=\"\${!var}\"
   local color=\"\$(eval \"printf '%s' \x5C\"\x5C\$Color_\${1:-}\x5C\"\" 2>/dev/null)\"
