# Last Parameter is Green, the rest are title
Say-Definition() {
  if [[ -z \"\$*\" ]]; then echo \"\"; return; fi
  # local args=(\"\$@\")
  # local title=\"\${args[@]:0:\$#-1}\"
  # local value=\"\${!#}\"
