  if [[ \"\$title\" != *\" \" ]] && [[ -n \"\$title\" ]]; then title=\"\$title \"; fi
  local colorTitle=\"\${DEFINITION_COLOR:-Yellow}\"
  local colorValue=\"\${VALUE_COLOR:-Green}\"
  Colorize --NoNewLine \"\$colorTitle\" \"\${title}\"
  Colorize \"\$colorValue\" \"\${value}\"
}

